    detail:"미 특수부대원 17명과 현지인 비정규군 약 410명이 지키던 고립된 기지에 북베트남군이 박격포와 소화기 공격을 집중했다. 계곡의 낮은 구름 때문에 항공 지원이 거의 불가능했고, 3일째 동쪽 방어선이 뚫렸다.\n\n혼란스러운 헬기 철수 과정에서 현지 비정규군 대부분이 남겨져 196~288명이 전사하거나 실종됐다. 이 패배로 북베트남군은 아사우 계곡을 완전히 장악해 호찌민 루트의 종착 기지로 요새화했고, 이곳은 1968년 구정 대공세 때 후에 공격의 발진 기지가 됐다.",
    mapDesign:"war-v1",mapNote:commonNote,mapView:[[107.18,15.97],[108.02,15.97],[108.02,16.51],[107.18,16.51]],
    routes:[["라오스 국경",107.42,16.28,"아사우 기지",107.55,16.20,"axis","land"],["아사우 기지",107.55,16.20,"철수 방향",107.90,16.32,"allied","air"]],
    zones:[{kind:"control",side:"axis",coordinates:[[107.36,16.06],[107.62,16.04],[107.70,16.34],[107.50,16.44],[107.30,16.28]],label:"북베트남군 장악(개략)",labelAt:[107.48,16.16]}],
    units:[{type:"infantry",side:"axis",at:[107.44,16.24],heading:110,label:"북베트남군 제325사단",showLabel:false},{type:"helicopter",side:"allied",at:[107.72,16.28],heading:60,label:"철수 헬기",showLabel:false}],
