    zones:[{kind:"control",side:"axis",coordinates:[[107.76,14.44],[108.06,14.42],[108.10,14.72],[107.84,14.78],[107.68,14.60]],label:"북베트남군 진출(개략)",labelAt:[107.88,14.62]},{kind:"contested",side:"neutral",coordinates:[[107.92,14.36],[108.10,14.34],[108.12,14.50],[107.96,14.54],[107.86,14.44]],label:"14번 도로 전선(개략)",labelAt:[108.02,14.44]}],
