    zones:[{kind:"control",side:"axis",coordinates:[[107.70,12.90],[108.60,12.86],[108.72,14.10],[107.96,14.20],[107.60,13.60]],label:"북베트남군 장악 고원(개략)",labelAt:[108.10,13.50]},{kind:"contested",side:"neutral",coordinates:[[109.06,12.90],[109.42,12.88],[109.46,13.24],[109.14,13.30],[108.98,13.10]],label:"해안 방어선(개략)",labelAt:[109.24,13.06]}],
