    units:[{type:"tank",side:"axis",at:[107.40,16.50],heading:140,label:"북베트남군 제2군단",showLabel:false},{type:"ship",side:"allied",at:[108.40,16.30],heading:70,label:"해상 철수",showLabel:false}],
