    zones:[{kind:"control",side:"axis",coordinates:[[107.10,10.94],[107.44,10.92],[107.50,11.22],[107.24,11.30],[107.04,11.10]],label:"북베트남군 진출(개략)",labelAt:[107.26,11.10]},{kind:"contested",side:"neutral",coordinates:[[106.94,10.86],[107.30,10.84],[107.32,10.98],[107.00,11.00],[106.90,10.92]],label:"1번 도로 전선(개략)",labelAt:[107.12,10.90]}],
